function pal(s: string): [string, string, string] {
  const parts = s.split(",").map((p) => `#${p.replace("#", "")}`);
  return [parts[0] ?? "#1e3a8a", parts[1] ?? "#e30613", parts[2] ?? "#f8fafc"];
}

export const COMICS: CatalogComic[] = rows.map(
  ([
    id,
    series,
    issue,
    publisher,
    coverDate,
    writers,
    artists,
    description,
    msrp,
    format,
    demand,
    key,
    palette,
    extra,
  ]) => ({
    id,
    series,
    issue,
    publisher,
    coverDate,
    streetDate: extra?.streetDate,
    writers: writers.split(",").map((w) => w.trim()),
    artists: artists.split(",").map((w) => w.trim()),
    description,
    msrp,
    format,
    variant: extra?.variant,
    upc: extra?.upc ?? UPC_MAP[id]?.upc,
    demand,
    key: key === 1,
    palette: pal(palette),
    // Prefer UPC-tied LOCG cover when present so variants keep distinct art
    cover: extra?.cover ?? UPC_MAP[id]?.coverUrl ?? (coverUrls as Record<string, string>)[id],
  }),
);

export const COMIC_BY_ID: Record<string, CatalogComic> = Object.fromEntries(
  COMICS.map((c) => [c.id, c]),
);

export const COMIC_SERIES = [...new Set(COMICS.map((c) => c.series))].sort();

export const COMIC_PUBLISHERS = [...new Set(COMICS.map((c) => c.publisher))].sort();

function comicKey(c: { series: string; issue: string; publisher: string; variant?: string }) {
  return `${c.series}|${c.issue}|${c.publisher}|${c.variant ?? ""}`.toLowerCase();
}

export function mergeComics(extras: CatalogComic[] = [], promoted: CatalogComic[] = []): CatalogComic[] {
  const seen = new Set(COMICS.map(comicKey));
  const out = [...COMICS];
  for (const c of [...promoted, ...extras]) {
    const k = comicKey(c);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(c);
  }
  return out;
}

export function comicById(
  id: string,
  extras: CatalogComic[] = [],
  promoted: CatalogComic[] = [],
): CatalogComic | undefined {
  return COMIC_BY_ID[id] ?? extras.find((c) => c.id === id) ?? promoted.find((c) => c.id === id);
}

export function searchComics(
  query: string,
  extras: CatalogComic[] = [],
  promoted: CatalogComic[] = [],
): CatalogComic[] {
  const list = mergeComics(extras, promoted);
  const q = query.trim().toLowerCase();
  if (!q) return list;
  const issueMatch = q.match(/#?\s*(\d+[a-z]?)$/i);
  return list.filter((c) => {
    const writers = Array.isArray(c.writers) ? c.writers.join(" ") : String(c.writers ?? "");
    const artists = Array.isArray(c.artists) ? c.artists.join(" ") : String(c.artists ?? "");
    const hay = `${c.series} ${c.issue} ${c.publisher} ${writers} ${artists} ${c.variant ?? ""} ${c.upc ?? ""}`.toLowerCase();
    if (hay.includes(q)) return true;
    if (issueMatch && c.issue === issueMatch[1] && hay.includes(q.replace(issueMatch[0], "").trim())) {
      return true;
    }
    return false;
  });
}

export function recentComics(limit = 10, extras: CatalogComic[] = [], promoted: CatalogComic[] = []): CatalogComic[] {
  return [...mergeComics(extras, promoted)].sort((a, b) => {
    const da = a.streetDate ?? a.coverDate;
    const db = b.streetDate ?? b.coverDate;
    return da < db ? 1 : -1;
  }).slice(0, limit);
}

export function comicLabel(c: { series: string; issue: string | number; variant?: string }) {
  const issueStr = String(c.issue ?? "").trim();
  const issue = issueStr.toLowerCase() === "nn" || !issueStr ? "" : ` #${issueStr}`;
  const variant = c.variant ? ` (${c.variant})` : "";
  return `${c.series}${issue}${variant}`;
}

